// Copy the app's own screenshots and logo into public/ at build time.
//
// Copied, not committed twice: docs/screenshots/ is regenerated by
// `npm run shots` from flows that assert what they photograph, and a second
// copy here would be the one that quietly goes stale.
import { cpSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const site = join(dirname(fileURLToPath(import.meta.url)), '..');
const repo = join(site, '..');

mkdirSync(join(site, 'public'), { recursive: true });
cpSync(join(repo, 'docs/screenshots'), join(site, 'public/screenshots'), { recursive: true });
cpSync(join(repo, 'assets/images/logo-mark.png'), join(site, 'public/logo-mark.png'));
cpSync(join(repo, 'assets/images/icon.png'), join(site, 'public/icon.png'));
console.log('copied screenshots and logo into public/');
